"""Linearizability checker for atomic range transactions.

Finds a serial witness order for a completed concurrent history, or proves
none exists.  A transaction is atomic: all its ops observe a state produced
by the preceding transactions plus its own earlier writes.

Algorithm: depth-first search over topological orders of the precedence DAG
(A must precede B when A.end <= B.start), simulating each transaction's ops
against the current state.  Search nodes are memoized on (executed-set,
state); a reached pair that cannot be extended to a solution is never
expanded again, which makes the search polynomial in the number of distinct
reachable (subset, state) pairs rather than in the number of permutations.

A forward prune uses per-key "leave value" sets: for the keys that no
remaining transaction can modify, the current state must already match the
final map; for keys that remaining transactions can modify, the final value
must belong to the set of values those transactions are able to leave.
"""

import json
import sys

GET, PUT, DEL, CAS, SCAN = 0, 1, 2, 3, 4


def solve(request):
    init = request['initial']
    fin = request['final']
    txs = request['transactions']
    n = len(txs)

    # ---- key universe -------------------------------------------------
    keyset = set(init) | set(fin)
    for t in txs:
        for op in t['ops']:
            if op[0] != 'scan':
                keyset.add(op[1])
    K = sorted(keyset)
    kn = len(K)
    kidx = {k: i for i, k in enumerate(K)}

    init_state = tuple(init.get(k) for k in K)
    fin_state = tuple(fin.get(k) for k in K)

    # ---- all values that may appear (for per-key leave analysis) ------
    vall = set()
    for v in init.values():
        vall.add(v)
    for v in fin.values():
        vall.add(v)
    for t in txs:
        for op in t['ops']:
            if op[0] == 'get':
                if op[2] is not None:
                    vall.add(op[2])
            elif op[0] == 'put':
                vall.add(op[2])
            elif op[0] == 'cas':
                if op[2] is not None:
                    vall.add(op[2])
                if op[3] is not None:
                    vall.add(op[3])
            elif op[0] == 'scan':
                for pair in op[3]:
                    vall.add(pair[1])
    V = list(vall)
    V.append(None)

    # ---- compile transactions -----------------------------------------
    compiled = []          # per tx: list of compact op tuples
    leave = []             # per tx: per key, frozenset of values it can leave
    for t in txs:
        cops = []
        per_key = [[] for _ in range(kn)]
        for op in t['ops']:
            name = op[0]
            if name == 'get':
                i = kidx[op[1]]
                cops.append((GET, i, op[2]))
                per_key[i].append((GET, op[2]))
            elif name == 'put':
                i = kidx[op[1]]
                cops.append((PUT, i, op[2]))
                per_key[i].append((PUT, op[2]))
            elif name == 'del':
                i = kidx[op[1]]
                cops.append((DEL, i))
                per_key[i].append((DEL,))
            elif name == 'cas':
                i = kidx[op[1]]
                cops.append((CAS, i, op[2], op[3], op[4]))
                per_key[i].append((CAS, op[2], op[3], op[4]))
            else:  # scan
                low, high, exp = op[1], op[2], op[3]
                cand = tuple(i for i, kk in enumerate(K) if low <= kk < high)
                mapped = []
                bad = False
                for kk, vv in exp:
                    j = kidx.get(kk)
                    if j is None:
                        bad = True  # key never present -> scan can never match
                        break
                    mapped.append((j, vv))
                # expected pairs must be key-sorted; an unsorted expectation
                # simply never matches the computed ascending tuple.
                cops.append((SCAN, cand, None if bad else tuple(mapped)))
        compiled.append(cops)
        lrow = [None] * kn
        for i in range(kn):
            ops_i = per_key[i]
            if not ops_i:
                continue
            if not any(o[0] != GET for o in ops_i):
                continue  # read-only on this key; not a modifier
            outs = set()
            for v0 in V:
                cur = v0
                ok = True
                for o in ops_i:
                    c = o[0]
                    if c == GET:
                        if cur != o[1]:
                            ok = False
                            break
                    elif c == PUT:
                        cur = o[1]
                    elif c == DEL:
                        cur = None
                    else:  # CAS
                        if (cur == o[1]) != o[3]:
                            ok = False
                            break
                        if cur == o[1]:
                            cur = o[2]
                if ok:
                    outs.add(cur)
            lrow[i] = frozenset(outs)
        leave.append(lrow)

    # ---- precedence: i before j iff end_i <= start_j -------------------
    pred = [0] * n
    for i in range(n):
        ei = txs[i]['end']
        bi = 1 << i
        for j in range(n):
            if i != j and ei <= txs[j]['start']:
                pred[j] |= bi

    # ---- rem_leave[mask]: union of leaveable values over remaining txs -
    full = (1 << n) - 1
    EMPTY = frozenset()
    rem_leave = [None] * (full + 1)
    rem_leave[full] = (EMPTY,) * kn
    for mask in range(full - 1, -1, -1):
        lowest_unset = (~mask & full) & -(~mask & full)
        t = lowest_unset.bit_length() - 1
        src = rem_leave[mask | (1 << t)]
        lt = leave[t]
        row = []
        for i in range(kn):
            li = lt[i]
            if li:
                si = src[i]
                row.append(si | li if si else li)
            else:
                row.append(src[i])
        rem_leave[mask] = tuple(row)

    # ---- simulate one transaction against a state tuple ----------------
    def simulate(ops, state):
        s = list(state)
        for op in ops:
            c = op[0]
            if c == GET:
                if s[op[1]] != op[2]:
                    return None
            elif c == PUT:
                s[op[1]] = op[2]
            elif c == DEL:
                s[op[1]] = None
            elif c == CAS:
                cur = s[op[1]]
                if (cur == op[2]) != op[4]:
                    return None
                if cur == op[2]:
                    s[op[1]] = op[3]
            else:  # SCAN
                got = tuple((i, s[i]) for i in op[1] if s[i] is not None)
                if got != op[2]:
                    return None
        return tuple(s)

    # ---- memoized DFS --------------------------------------------------
    shift = 5 * kn + 1
    memo = set()
    sys.setrecursionlimit(max(10000, n + 100))

    def encode(state):
        e = 0
        for i in range(kn - 1, -1, -1):
            v = state[i]
            e = e * 20 + (0 if v is None else v + 10)
        return e

    def dfs(mask, state):
        # forward prune against the final map
        L = rem_leave[mask]
        for i in range(kn):
            Li = L[i]
            if Li:
                if fin_state[i] not in Li:
                    return None
            elif state[i] != fin_state[i]:
                return None
        if mask == full:
            return []
        key = (mask << shift) | encode(state)
        if key in memo:
            return None
        for t in range(n):
            if not (mask >> t) & 1 and not (pred[t] & ~mask):
                ns = simulate(compiled[t], state)
                if ns is not None:
                    r = dfs(mask | (1 << t), ns)
                    if r is not None:
                        r.append(t)
                        return r
        memo.add(key)
        return None

    res = dfs(0, init_state)
    if res is None:
        return {'order': None}
    return {'order': [txs[t]['id'] for t in reversed(res)]}


def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            res = solve(json.loads(line))
        except Exception:
            import traceback
            traceback.print_exc(file=sys.stderr)
            res = {'order': None}
        out.append(json.dumps(res))
    if out:
        sys.stdout.write('\n'.join(out) + '\n')


if __name__ == '__main__':
    main()
