import itertools, json, sys
sys.path.insert(0, '/app')
from public_contract import valid_history

def brute_solve(request):
    """Reference: try every permutation consistent with precedence."""
    txs = request['transactions']
    n = len(txs)
    pred = [set() for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and txs[i]['end'] <= txs[j]['start']:
                pred[j].add(i)
    for perm in itertools.permutations(range(n)):
        pos = {t: k for k, t in enumerate(perm)}
        ok = True
        for j in range(n):
            if any(pos[i] > pos[j] for i in pred[j]):
                ok = False
                break
        if not ok:
            continue
        order = [txs[t]['id'] for t in perm]
        if valid_history(request, order):
            return {'order': order}
    return {'order': None}
