def gen_request(rng, n_tx=None, n_ops=None, n_keys=None, allow_scans=True):
    keys = [k for k in ['a','b','c','d','e','f']]
    if n_keys is None:
        n_keys = rng.randint(1, 6)
    keys = keys[:n_keys]
    if n_tx is None:
