    txs = []
    for i in range(n_tx):
        s = rng.randint(0, 8)
        e = s + rng.randint(1, 4)
        if rng.random() < 0.5:
            # overlapping intervals
            s = rng.randint(0, 3); e = rng.randint(5, 9)
        ops = []
        m = n_ops if n_ops is not None else rng.randint(1, 5)
        for _ in range(m):
            r = rng.random()
            k = rng.choice(keys)
            if r < 0.25:
                exp = rng.choice([None, rng.randint(-2, 2)])
                ops.append(['get', k, exp])
            elif r < 0.5:
                ops.append(['put', k, rng.randint(-2, 2)])
            elif r < 0.62:
                ops.append(['del', k])
            elif r < 0.8:
                old = rng.choice([None, rng.randint(-2, 2)])
                new = rng.choice([None, rng.randint(-2, 2)])
                want = rng.choice([True, False])
                ops.append(['cas', k, old, new, want])
            elif allow_scans:
                ks2 = ['a','b','c','d','e','f','g']
                lo = rng.choice(ks2[:n_keys+1])
                hi = rng.choice(ks2[:n_keys+1])
                if lo >= hi:
                    lo, hi = 'a', 'z'
                exp = []
                for kk in keys:
                    if lo <= kk < hi and rng.random() < 0.5:
                        exp.append([kk, rng.randint(-2, 2)])
                exp.sort()
                ops.append(['scan', lo, hi, exp])
            else:
                ops.append(['put', k, rng.randint(-2, 2)])
        txs.append({'id': f't{i}', 'start': s, 'end': e, 'ops': ops})
    init = {}
    for k in keys:
        if rng.random() < 0.4:
            init[k] = rng.randint(-2, 2)
    fin = {}
    for k in keys:
        if rng.random() < 0.5:
            fin[k] = rng.randint(-2, 2)
    return {'initial': init, 'final': fin, 'transactions': txs}
